import{_ as t,o as r,c as a,a3 as i}from"./chunks/framework.BwzYn71E.js";const f=JSON.parse('{"title":"Feedforward Without Priority?","description":"","frontmatter":{"head":[["link",{"rel":"canonical","href":"https://kokobird28144.github.io/endfield-skydoc/feedforward-without-priority"}]],"lang":"en-US","translationSource":{"title":"无优先级的前馈？","archivedAt":"2026-10-23T14:20:34.857Z","url":"https://docs.qq.com/aio/DTmluZ1diWlpQZldw?p=BMwOTfe25aJKA3BVsZfIAh","scope":"page"}},"headers":[],"relativePath":"feedforward-without-priority.md","filePath":"logistics/src/page-BMwOTfe25aJKA3BVsZfIAh.md","lastUpdated":null}'),o={name:"feedforward-without-priority.md"};function n(s,e,c,d,l,h){return r(),a("div",null,[...e[0]||(e[0]=[i('<div class="logistics-content"><span class="logistics-source-anchor" id="无优先级的前馈" aria-hidden="true"></span><h1 id="feedforward-without-priority" tabindex="-1">Feedforward Without Priority? <a class="header-anchor" href="#feedforward-without-priority" aria-label="Permalink to &quot;Feedforward Without Priority?&quot;">​</a></h1><blockquote><p>Source page ID: <code>BMwOTfe25aJKA3BVsZfIAh</code> ｜ <a href="https://docs.qq.com/aio/DTmluZ1diWlpQZldw?p=BMwOTfe25aJKA3BVsZfIAh" target="_blank" rel="noreferrer">Open in Tencent Docs</a></p></blockquote><p>Before engineering implementation, first consider whether this structure is theoretically valid.</p><p>In classical logic, feedforward works as follows: the input is split by a generalized splitter (or a complementer) into a discard branch and an activation branch. A basic control structure then blocks the discard branch when raw materials are sufficient, causing the splitter to send the input to the activation branch and achieving the logic “raw material sufficient → more activators on the activation path.”</p><p>In implementations, the discard branch is usually connected to a priority merger at the input, producing an effect similar to discarding back into storage. Now consider removing priority without changing the structure; in that case, we must choose where the discard branch goes.</p></div>',1)])])}const u=t(o,[["render",n]]);export{f as __pageData,u as default};
